import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath}from'node:url';
import {eighthEntry} from '../eighth-reconciliation/verify-dependencies.mjs';
const home=path.dirname(fileURLToPath(import.meta.url)),read=n=>JSON.parse(fs.readFileSync(path.join(home,n),'utf8')),sha=s=>crypto.createHash('sha256').update(s).digest('hex'),plain=s=>s.replace(/<[^>]*>/g,'').replaceAll('&gt;','>').replaceAll('&lt;','<').replaceAll('&amp;','&').replaceAll('&#39;',"'").replaceAll('&quot;','"');
export const names=['seven guarded leaves are actually applied','one real-compiler append preserves complete old prefix','old identities and all unowned fields are unchanged','all 163 source blocks retain substantive destinations','all 70 exact source wordings remain on original questions','read-only canonical and explicit candidate dependencies exist','Judge denominators and kappa calculation are correct','unique release Prompt and video conditions are retained','HTML anchors and internal routes are valid','public prose does not claim unrun experiments or expose editing labels'];
function balanced(s){let st=[];const voids=new Set(['br','hr','img','input','meta','link','wbr']);for(let m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){let t=m[2].toLowerCase();if(m[1])assert.equal(st.pop(),t,'unbalanced '+t);else if(!voids.has(t)&&!m[0].endsWith('/>'))st.push(t);}assert.deepEqual(st,[]);}
export function verify(dist){const entries=[];for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(f=>f.endsWith('.json')))entries.push(...JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f),'utf8')).entries);const E=new Map(entries.map(e=>[e.id,e]));assert.equal(E.size,entries.length);const get=k=>{const [id,q]=k.split('#');let e=E.get(id);assert.ok(e,'missing entry '+id);if(q===undefined)return e;let it=e.items?.find((x,i)=>String(x.id??i)===q);assert.ok(it,'missing question '+k);return it;};
const R=read('records.json').records,A=read('append-manifest.json'),B=read('identity-baseline.json'),M=read('preservation-map.json'),V=read('variant-map.json'),S=read('sections.json'),D=read('external-dependencies.json'),checks=[];const actual=r=>r.path.reduce((x,k)=>x[k],E.get(r.entryId));const actualBodies=()=>R.map(r=>r.mode==='exact-old-prefix-plus-append'?actual(r).slice(r.before.length):actual(r)).concat(A.additions.map(a=>get(a.entryId+'#'+a.questionId).a));const run=(name,fn)=>{try{fn();checks.push({name,passed:true});}catch(e){checks.push({name,passed:false,error:e.message});}};
run(names[0],()=>{assert.equal(R.length,7);assert.equal(new Set(R.map(r=>r.entryId+JSON.stringify(r.path))).size,7);for(let r of R){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);let actual=r.path.reduce((x,k)=>x[k],E.get(r.entryId));assert.equal(actual,r.after,'UNAPPLIED_OR_CHANGED '+r.entryId+'/'+r.path.join('/'));}let media=R.find(r=>r.entryId==='own-theory-media');assert.equal(media.mode,'exact-old-prefix-plus-append');assert.ok(media.after.startsWith(media.before));});
run(names[1],()=>{assert.equal(A.additions.length,1);let a=A.additions[0],e=get(a.entryId);assert.equal(a.expectedIndex,3);assert.equal(a.expectedOldCount,3);assert.equal(a.questionId,'q-prompt-lifecycle-evaluation');assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);assert.equal(sha(a.expectedItem.a),a.afterSha256);assert.deepEqual(e.items.slice(0,3),eighthEntry(A.completeBeforeEntry).items);assert.deepEqual(A.completeAfterAppendEntry.items.slice(0,3),A.completeBeforeEntry.items);assert.deepEqual(e.items[3],a.expectedItem);assert.equal(e.items.length,4);assert.equal(e.number,'4 问');});
run(names[2],()=>{for(let old of B.entries){const e=get(old.id),expected=structuredClone(old);for(let r of R.filter(r=>r.entryId===old.id)){let x=expected;for(let k of r.path.slice(0,-1))x=x[k];x[r.path.at(-1)]=r.after;}for(let a of A.additions.filter(a=>a.entryId===old.id)){expected.items.push(a.expectedItem);expected.number='4 问';}assert.deepEqual(e,eighthEntry(expected),'changed old complete object '+old.id);}});
run(names[3],()=>{assert.equal(M.maps.length,163);assert.equal(M.sourceBlockCount,163);for(let key of ['ai-模型与评测-6#0','ai-模型与评测-6#2','ai-模型与评测-6#4']){const i=Number(key.split('#')[1]),r=R.find(r=>r.entryId==='ai-模型与评测-6'&&r.path[1]===i&&r.path[2]==='a'),bs=[...r.before.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)],maps=M.maps.filter(m=>m.sourceKey===key);assert.equal(bs.length,maps.length);for(let [j,m]of maps.entries()){assert.equal(m.sourceBlockIndex,j);assert.equal(m.sourceHtml,bs[j][0]);assert.equal(sha(m.sourceHtml),m.sourceSha256);assert.equal(Array.from(r.before).slice(...m.sourceSpanCodePoints).join(''),m.sourceHtml);assert.ok(m.destinations.length);for(let d of m.destinations){assert.equal(sha(d.html),d.sha256);let fr=d.fragments||[d.html];assert.ok(fr.some(z=>/<(?:p|li)\b/.test(z)),'heading only');for(let z of fr){assert.ok(plain(z).length>35,'insubstantial witness');assert.ok(get(d.stableReviewKey).a.includes(z),d.stableReviewKey+' missing witness for '+key+' block '+j);}}}}});
run(names[4],()=>{assert.equal(V.originalCount,70);assert.equal(V.variants.length,70);for(let i of [0,2,4]){let vs=V.variants.filter(v=>v.sourceIndex===i);assert.equal(vs.length,{0:16,2:17,4:37}[i]);const r=R.find(r=>r.entryId==='ai-模型与评测-6'&&r.path[1]===i&&r.path[2]==='a'),a=get('ai-模型与评测-6#'+i).a;let folds=[...a.matchAll(/<details\b[^>]*>[\s\S]*?<\/details>/g)].map(m=>m[0]).join('');for(let v of vs){assert.ok(r.before.includes(v.html));assert.equal(sha(v.html),v.sourceSha256);assert.ok(plain(folds).includes(v.text),'lost wording '+v.text);assert.ok(v.destinations.length);}let count=[...folds.matchAll(/<li\b/g)].length;assert.equal(count,vs.length);}});
run(names[5],()=>{for(let d of D.dependencies){assert.equal(sha(d.html),d.sha256);for(let f of d.fragments||[d.html])assert.ok(get(d.stableReviewKey).a.includes(f),d.name+' missing exact canonical witness');}for(let dep of D.crossWorker){assert.match(dep.expectedFullAfterSha256||'',/^[a-f0-9]{64}$/,'unfrozen dependency '+dep.key);assert.equal(sha(get(dep.key).a),dep.expectedFullAfterSha256,dep.key+' candidate body drift');}for(let dep of D.routeDependencies){assert.equal(sha(JSON.stringify(get(dep.key))),dep.expectedItemSha256,dep.key+' routed candidate drift');assert.equal(sha(get(dep.key).a),dep.afterSha256);}});
run(names[6],()=>{let a=get('ai-模型与评测-6#4').a;for(let t of ['(TP+TN)/N','FP/(FP+TN)','FP/(TP+FP)','FN/(TP+FN)','TP=72','TN=18','FP=2','FN=8','2/20=10%','2.70%','8/80=10%','κ=(pₒ−pₑ)/(1−pₑ)','0.8×0.74+0.2×0.26=0.644','0.719','pₑ=1','类别极不平衡','相差几档','相关性高','小样本里恰好零误放','反复用测试集','真实欺诈概率'])assert.ok(a.includes(t),'Judge lost '+t);let tp=72,tn=18,fp=2,fn=8,N=tp+tn+fp+fn;assert.equal((tp+tn)/N,.9);assert.equal(fp/(fp+tn),.1);assert.equal(fn/(tp+fn),.1);assert.ok(Math.abs(fp/(tp+fp)-.027027027)<1e-8);let pe=((tp+fn)*(tp+fp)+(tn+fp)*(tn+fn))/(N*N);assert.equal(pe,.644);assert.ok(Math.abs((.9-pe)/(1-pe)-.719101124)<1e-8);assert.equal(1-1,0);});
run(names[7],()=>{const expected={'ai-模型与评测-6#0':['三类管理职责','普通后端也有','时点一致性'],'ai-上下文工程-5#q-prompt-lifecycle-evaluation':['车型参数、年款、区域、配置、价格和生效期','不能用另一年款默认补齐','不能运行时随意拼最新版本','不声称缓存失效就完成撤回','不能挑最好一次','最终保留集不反复参与搜索','搜索次数和费用上限','框架不是必选','只接收已声明且通过校验的模板变量','固定消息角色与模板结构','只能降低结构层面的注入风险','不能阻止用户文本或检索材料中的语义诱导','不可信内容仍应作为数据处理','工具权限、参数校验与高风险动作授权必须由宿主独立执行'],'ai-模型与评测-6#2':['权重文件、adapter、量化格式','不能重置循环预算','KV 未经兼容验证','已撤销策略','后台队列','保留/训练设置','十万连接不等于十万条同时解码','若同时迁移了权威数据存储位置','若只是切换模型、仍共享同一权威库','同 key 不同修复 payload','CDC 断档','补偿超时 UNKNOWN','7B/72B'],'own-theory-media#q-own-theory-media-task-spec':['镜头/事实覆盖','字幕是否越界','卡帧','缺音','音画时间关系','授权素材范围','抽到几帧不能证明全片','叙事连贯、节奏、情绪、品牌适配与可理解性','严重缺陷率、可用成片率、返工次数','生成、理解还是编辑']};for(let [k,terms]of Object.entries(expected))for(let t of terms)assert.ok(get(k).a.includes(t),k+' missing '+t);assert.ok(!get('ai-上下文工程-5#q-prompt-lifecycle-evaluation').a.includes('只允许已声明变量注入，缺参报错，避免用户文本通过字符串拼接覆盖系统指令。'),'old structure-only overstatement remains');});
run(names[8],()=>{let bodies=actualBodies();for(let r of R)for(let m of r.before.matchAll(/\bid="([^"]+)"/g))assert.ok(actual(r).includes(m[0]));for(let b of bodies){balanced(b);for(let m of b.matchAll(/href="#\/e\/([^"#]+)"/g)){let [e,q]=m[1].split('/').map(decodeURIComponent);get(e+(q===undefined?'':'#'+q));}}});
run(names[9],()=>{let bodies=actualBodies().join('');assert.ok(!/<(?:pre|code)\b/.test(bodies));assert.ok(!/原题变体索引|已完成GPU实验|实测提升了|我们已经达到/.test(bodies));assert.ok(get('ai-模型与评测-6#4').a.includes('不是个人实测'));assert.ok(get('ai-模型与评测-6#2').a.includes('不能把待测方案或预期输出当成实绩'));});
return {passed:checks.every(x=>x.passed),checks,mode:'actual-dist-only',dist:path.resolve(dist),overlay:false,siteWrites:0,limitations:['Read-only content and mathematical contract checks only. No model/provider/GPU/video experiment, full site build, or browser acceptance.','Final acceptance requires already-integrated actual dist, never an overlay or fallback.']};}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const args=process.argv.slice(2);assert.equal(args.length,2,'Only --dist PATH is accepted');assert.equal(args[0],'--dist','Only --dist PATH is accepted');assert.ok(path.isAbsolute(args[1]),'dist path must be explicit and absolute');try{let r=verify(args[1]);console.log(JSON.stringify(r,null,2));if(!r.passed)process.exitCode=1;}catch(e){console.error(e.stack);process.exitCode=1;}}
